import type { Locale } from "@/i18n/config";
import { RFQ_COUNTRY_CODES } from "./countries";

export type RFQCountryOption = { code: string; name: string };

// Generated by the server page and serialized to the client, so hydration uses
// the exact same labels even when the browser and server have different ICU data.
export function getRFQCountryOptions(locale: Locale): RFQCountryOption[] {
  const names = new Intl.DisplayNames([locale], { type: "region" });
  return RFQ_COUNTRY_CODES.map((code) => ({ code, name: names.of(code) ?? code }));
}
